mapper.update:
    UPDATE T_AIRPORT_CODE SET 
    apcd_icao_code=#{apcdIcaoCode},
    apcd_airport_name=#{apcdAirportName},
    apcd_airport_name_s=#{apcdAirportNameS},
    apcd_cnaf_airport_code=#{apcdCnafAirportCode},
    apcd_protocol=#{apcdProtocol},
    apcd_airport_prop=#{apcdAirportProp}
    
	,apcd_vkorg=#{apcdVkorg}
	,apcd_vtweg=#{apcdVtweg}
	,apcd_bwtar=#{apcdBwtar}
	,apcd_werks=#{apcdWerks}
	,apcd_vkbur=#{apcdVkbur}
	,apcd_vkgrp=#{apcdVkgrp}
	,apcd_orgeh=#{apcdOrgeh}
	,apcd_persa=#{apcdPersa}
	,apcd_btrtl=#{apcdBtrtl}
    
    
    WHERE apcd_iata_code=#{apcdIataCode}

mapper.delete:
DELETE
FROM T_AIRPORT_CODE
WHERE apcd_iata_code=#{apcdIataCode}
AND apcd_icao_code=#{apcdIcaoCode}

mapper.select:
SELECT apcd_iata_code AS apcdIataCode, apcd_icao_code AS apcdIcaoCode, apcd_airport_name AS apcdAirportName, apcd_airport_name_s AS apcdAirportNameS, apcd_cnaf_airport_code AS apcdCnafAirportCode, apcd_protocol AS apcdProtocol, apcd_airport_prop AS apcdAirportProp
,apcd_vkorg AS apcdVkorg, apcd_vtweg AS apcdVtweg, apcd_bwtar AS apcdBwtar, apcd_werks AS apcdWerks, apcd_vkbur AS apcdVkbur, apcd_vkgrp AS apcdVkgrp, apcd_orgeh AS apcdOrgeh, apcd_persa AS apcdPersa, apcd_btrtl AS apcdBtrtl
FROM T_AIRPORT_CODE WHERE apcd_iata_code=#{apcdIataCode}

SELECT apcd_iata_code AS apcdIataCode, apcd_icao_code AS apcdIcaoCode, apcd_airport_name AS apcdAirportName, apcd_airport_name_s AS apcdAirportNameS, apcd_cnaf_airport_code AS apcdCnafAirportCode, apcd_protocol AS apcdProtocol, apcd_airport_prop AS apcdAirportProp
,apcd_vkorg AS apcdVkorg, apcd_vtweg AS apcdVtweg, apcd_bwtar AS apcdBwtar, apcd_werks AS apcdWerks, apcd_vkbur AS apcdVkbur, apcd_vkgrp AS apcdVkgrp, apcd_orgeh AS apcdOrgeh, apcd_persa AS apcdPersa, apcd_btrtl AS apcdBtrtl
FROM T_AIRPORT_CODE WHERE apcd_cnaf_airport_code=#{apcdCnafAirportCode}
